// All names and paths are generated by the native plugin, never by the caller.
export function createIosTemporaryFactory(plugin) {
  if (!plugin?.begin || !plugin?.append || !plugin?.commit || !plugin?.abort) throw new Error("Pont de sauvegarde iPhone indisponible.");
  return async function openTemporary() {
    const { id } = await plugin.begin();
    if (typeof id !== "string" || !id) throw new Error("Sauvegarde temporaire indisponible.");
    let active = true;
    return {
      sink: { async write(bytes) {
        if (!active) throw new Error("Sauvegarde déjà terminée.");
        for (let offset = 0; offset < bytes.length; offset += 48 * 1024) {
          let text = "";
          for (const byte of bytes.subarray(offset, offset + 48 * 1024)) text += String.fromCharCode(byte);
          await plugin.append({ id, data: btoa(text) });
        }
      } },
      async commit() { if (!active) throw new Error("Sauvegarde déjà terminée."); const result = await plugin.commit({ id }); active = false; return result; },
      async abort() { if (active) { active = false; await plugin.abort({ id }); } }
    };
  };
}
